bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 60
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'JS'
import pg from 'pg';import {readFileSync} from 'node:fs';
const e=process.env;let pool=null;
try{
 const pw=readFileSync('/run/secrets/videobot_db_password','utf8').trim();
 pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:pw,max:1,connectionTimeoutMillis:5000});
 const a=await pool.query("SELECT COUNT(*)::int AS n FROM videobot_post_receipts");
 if(a.rows[0].n<1)process.exitCode=71;
 else {
  const old=await pool.query("SELECT listing_id,revision,status,paid_message_id FROM videobot_post_receipts WHERE paid_message_id=4691");
  if(old.rowCount!==1)process.exitCode=72;
  else{
   const b=await pool.query("SELECT revision,status,paid_message_id FROM videobot_post_receipts WHERE listing_id=$1 ORDER BY revision DESC",[old.rows[0].listing_id]);
   if(b.rowCount<2)process.exitCode=73;
   else if(!b.rows.some(x=>x.status==='sent'))process.exitCode=74;
   else console.log('TWO_VIDEO_VERSIONS_DB_LOOKUP=PASS');
  }
 }
}catch(e){
 const c=e?.code;
 process.exitCode=c==='42P01'?81:c==='42703'?82:c==='28P01'?83:c==='ETIMEDOUT'?84:89;
}finally{if(pool)await pool.end()}
JS
